"""Fixed replay panel, preservation checks, manifests, and scientific report."""
import os,sys
sys.dont_write_bytecode=True
for k in ['OPENBLAS_NUM_THREADS','OMP_NUM_THREADS','MKL_NUM_THREADS']:os.environ[k]='1'
from pathlib import Path
import json,csv,subprocess,hashlib,datetime
P=Path(__file__).resolve().parent;ROOT=P.parents[2]
run=Path(sys.argv[1] if len(sys.argv)>1 else (P/'LATEST_RUN.txt').read_text().strip());os.environ['STAGE2H_RUN']=str(run)
from common_h0 import load,dump,sha,table
from run_pilot import snapshot
def rows(p):return list(csv.DictReader(p.open(encoding='utf-8')))
def main():
 # Locked before fitting: first sample, median, kappa=1, truth in both n/arms.
 ids=[f'n{n}_r01_t50_k100_c1_{arm}' for n in [500,1000] for arm in ['A','B']]
 (run/'results/replay').mkdir(exist_ok=True);replays=[]
 for id in ids:
  f=run/'results/replay'/id
  if not (f/'result.json').exists():
   with (run/'results/replay'/(id+'.log')).open('x',encoding='utf-8') as log:
    subprocess.run([sys.executable,'-B',str(P/'candidate_h0.py'),id,'replay'],cwd=ROOT,stdout=log,stderr=subprocess.STDOUT,check=True,timeout=180)
  a=load(run/'results/pilot'/id/'result.json');b=load(f/'result.json')
  identical=a.get('fingerprints')==b.get('fingerprints') if a['status']==b['status']=='PASS' else None
  replays.append({'id':id,'original_status':a['status'],'replay_status':b['status'],'all_numerical_fingerprints_identical':identical,'statistical_replications_added':0})
 table(run/'reproducibility.csv',replays)
 assert all(r['all_numerical_fingerprints_identical'] for r in replays),'Replay failure retained; investigate before claiming reproducibility'
 before=load(run/'protected_before.json');after=snapshot();changed=[k for k in before if before[k]!=after.get(k)];added=sorted(set(after)-set(before))
 gitbefore=load(run/'git_before.json');gitafter={str(f.relative_to(ROOT)):sha(f) for f in (ROOT/'.git').rglob('*') if f.is_file()}
 preservation={'status':'PASS' if not changed and not added and gitbefore==gitafter else 'FAIL','changed_or_missing':changed,'new_files_outside_pilot':added,'git_metadata_unchanged':gitbefore==gitafter,'protected_files':len(before)}
 dump(run/'preservation.json',preservation);assert preservation['status']=='PASS'
 for name,h in load(run/'SOURCE_LOCK.json').items():assert sha(ROOT/name)==h,name
 for name,h in load(run/'INPUT_LOCK.json').items():assert sha(run/name)==h,name
 summary=load(run/'SUMMARY.json');execution=load(run/'EXECUTION.json');stats=rows(run/'coverage_rejection_summary.csv');paired=rows(run/'paired_comparisons.csv');raw=rows(run/'raw_evaluations.csv')
 out=['# Stage 2H prespecified paired diagnostic pilot','',f"Run `{run.name}`. Fixed design: n=500/1000, p=100, s=7, rho=.3, tau=.1/.5/.9, kappa=1/.1, R=20 per cell, arms original and .05+.90 Phi(T), candidates truth+{{-.5,0,.5}}. Seed 2026110281, R 3.4.3 L’Ecuyer-CMRG/Inversion. Two one-thread workers; unchanged 2G-D.1/H0 numerical policy.",'',f"Planned **1,440 individual evaluations (720 pairs)**; attempted **{summary['attempted']}**, numerically qualified **{summary['qualified']}**, unresolved/not executed **{summary['unresolved_or_not_executed']}**. At truth: {summary['truth_qualified']} qualified of 480 planned. Successful counts require every certificate and independent audit; missing decisions remain in denominator 20. Four prespecified same-input replays add no statistical observations.",'',f"Measured candidate execution wall time: {execution['elapsed_seconds']/3600:.3f} hours; sampled aggregate peak RSS: {execution['memory']['sampled_tree_peak_RSS_bytes']/2**20:.1f} MiB. This sampled RSS counts shared pages and is not a continuous maximum. Preparation/replay/audit costs and raw logs remain separately available. Planning base/twofold estimates were 2.52/5.04 hours and 9.34/18.69 GiB; resource envelopes were 12 hours, 20 GiB and at least 2 GiB available memory. External candidate limit: 180 seconds.",'','## Truth inclusion and paired comparisons','', 'Each row has 20 planned independent base samples. Intervals are pointwise. Coverage bounds include all unresolved/not-executed decisions; qualified-only comparisons are additional diagnostics.','', '| n | tau | kappa | A coverage bounds | B coverage bounds | qualified pairs | paired coverage B−A bounds | complete-pair MCSE | paired W B−A (MCSE) |','|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
 for p in paired:
  if float(p['offset'])!=0:continue
  ss=[s for s in stats if all(s[k]==p[k] for k in ['n','tau','kappa']) and float(s['offset'])==0];a=next(s for s in ss if s['arm']=='A');b=next(s for s in ss if s['arm']=='B')
  def fmt(v):return f'{float(v):.3f}' if v not in ['',None] else 'NA'
  out.append('| '+' | '.join([p['n'],p['tau'],p['kappa'],f"[{fmt(a['acceptance_lower'])},{fmt(a['acceptance_upper'])}]",f"[{fmt(b['acceptance_lower'])},{fmt(b['acceptance_upper'])}]",p['complete_pairs'],f"[{fmt(p['acceptance_B_minus_A_lower'])},{fmt(p['acceptance_B_minus_A_upper'])}]",fmt(p['complete_acceptance_difference_MCSE']),f"{fmt(p['complete_W_difference_mean'])} ({fmt(p['complete_W_difference_MCSE'])})"])+ ' |')
 out+=['','The full `coverage_rejection_summary.csv` supplies truth rejection, off-truth rejection/power separately at −.50 and +.50, exact Clopper–Pearson intervals for both extreme completions, plug-in MCSEs, qualified-only W means/SD/median/quantiles and counts. `paired_comparisons.csv` gives all-planned missing-decision bounds, complete-pair differences/MCSEs, discordances and exact discordance bounds. Zero plug-in MCSE is not certainty. Cells sharing primitives are never pooled as independent replications.','', '## Numerical status and validation','']
 from collections import Counter
 out.append('Evaluation statuses: '+json.dumps(dict(Counter(r['status'] for r in raw)))+'. Failure components: '+json.dumps(dict(Counter(r['component'] for r in raw if r['component'])))+'.')
 out+=['','`input_validation.csv` independently replays all 40 primitive streams and 720 penalty streams, reconstructs both arms and structural truth, and checks primitive/penalty pairing and before/after RNG states. `numerical_validation.csv` independently reconstructs every qualified saved score/moment/W; each candidate retains direct rational certificates and independent audits, including failed-attempt audit records. `reproducibility.csv` verifies the frozen four-case replay panel bitwise. The cutoff bytes remain 5.99146454710798. `preservation.json` verifies all protected repository files and Git metadata.','', '## DGP mechanisms and theory','',f"Sample covariance scales by .90, treatment variance by .81, and first-stage partial R²/F remain unchanged to maximum absolute error {summary['relevance_affine_identity_max_error']:.3g}. `instrument_relevance.csv` retains every sample, including kappa=.10; `numerical_diagnostics.csv` records instrument residual variances, score eigenvalues/conditioning, density extrema, KKT/objective bounds and W certificate widths. The historical density proxy remains dnorm(e,mean(e),var(e)), with variance as scale; its meaning is not silently replaced by the true conditional density.",'','The structural effect remains 1+Phi⁻¹(tau), and the structural residual is D(u−Phi⁻¹(tau)); primitive ranks and rank moments are preserved. The bounded arm changes support, dispersion, endogeneity covariance and instrument covariance while preserving linear first-stage R². It therefore does not isolate density regularity as the only changed mechanism. Bounded mixed residual densities are finite and positive; the original mixed density at zero diverges. The uniform density lower bound conditional on D,X,Z remains zero. Treatment itself is not uniform and its density can diverge at support edges. See the frozen readiness derivation for the proofs and analytical local-profile Jacobians.','', 'These numerical certificates qualify the computed fixed objectives, not the statistical approximation. Any paired statistical difference is conditional on this numerical policy and subject to Monte Carlo sampling error; R=20 has ideal .95-coverage MCSE about .0487. Near-95% acceptance or an improvement in B cannot establish asymptotic validity. Sparse/restricted eigenvalues, nuisance rates and orthogonality of the retained proxy/residualization, generated-score theory, cross-fitting/empirical-process conditions and weak-instrument approximation remain unproved.','', '## Manuscript implications and next scientific task','', 'Use these results as a finite prespecified DGP-sensitivity diagnostic, with full numerical resolution rates and pointwise Monte Carlo uncertainty. Do not report continuous interval geometry from a three-point profile or claim that bounded treatment validates the original inference theorem. The manuscript was not modified. The next task is an explicit assumption-by-assumption mapping to the intended inference theorem, focusing on conditioning sets, nuisance orthogonality/rates and weak-instrument validity; any larger simulation or revised policy needs a separately frozen protocol.','', '## Reproduction and preservation','', 'Commands, adapters and RNG layout are in the pilot README and `CONFIG.json`; logs, environment/session information, source/input hashes and raw binary/RDS records are retained under the immutable run directory. No historical output was overwritten. No commit or push was made.']
 (P/'STAGE2H_REPORT.md').write_text('\n'.join(out)+'\n',encoding='utf-8')
 files={str(f.relative_to(P)): {'sha256':sha(f),'bytes':f.stat().st_size} for f in P.rglob('*') if f.is_file() and f.name!='SHA256_MANIFEST.json'}
 dump(P/'SHA256_MANIFEST.json',files)
 print(summary,preservation,flush=True)
if __name__=='__main__':main()
